case class SwapRequest(tokenIn: String, tokenOut: String, amountIn: BigDecimal, minAmountOut: BigDecimal, deadline: Long)
case class SwapResponse(txHash: String, amountOut: BigDecimal, effectivePrice: BigDecimal)
case class PriceQuote(token: String, price: BigDecimal, timestamp: Long)

implicit val swapReqFormat = jsonFormat5(SwapRequest)
implicit val swapResFormat = jsonFormat3(SwapResponse)
implicit val priceFormat = jsonFormat3(PriceQuote)

class RateLimiter(maxRequests: Int, windowMs: Long) {
  private val requests = new AtomicLong(0)
  private val windowStart = new AtomicLong(System.currentTimeMillis())

  def tryAcquire(): Boolean = {
    val now = System.currentTimeMillis()
    if (now - windowStart.get() > windowMs) {
      windowStart.set(now)
      requests.set(1)
      true
    } else {
      requests.incrementAndGet() <= maxRequests
    }
  }
}

class PriceOracle(implicit ec: ExecutionContext) {
  private val priceCache = new AtomicReference[Map[String, PriceQuote]](Map.empty)
  private val lastUpdate = new AtomicLong(0)
  private val UPDATE_INTERVAL_MS = 1000L

  def getPrice(token: String): Future[PriceQuote] = Future {
    val cached = priceCache.get()
    val now = System.currentTimeMillis()
    if (now - lastUpdate.get() > UPDATE_INTERVAL_MS || !cached.contains(token)) {
      val freshPrice = fetchExternalPrice(token)
      priceCache.set(cached + (token -> freshPrice))
      lastUpdate.set(now)
      freshPrice
    } else {
      cached(token)
    }
  }

  private def fetchExternalPrice(token: String): PriceQuote = {
    // Simulates external oracle call
    val basePrice = token match {
      case "ETH" => BigDecimal("2000.00")
      case "USDC" => BigDecimal("1.00")
      case "WBTC" => BigDecimal("43000.00")
      case _ => BigDecimal("0.01")
    }
    PriceQuote(token, basePrice, System.currentTimeMillis())
  }
}

class SwapEngine(oracle: PriceOracle)(implicit ec: ExecutionContext) {
  private val poolReserves = new AtomicReference[Map[String, BigDecimal]](
    Map("ETH" -> BigDecimal("10000"), "USDC" -> BigDecimal("20000000"), "WBTC" -> BigDecimal("500"))
  )
  private val SLIPPAGE_TOLERANCE = BigDecimal("0.005") // 0.5%
  private val MAX_SINGLE_TRADE_RATIO = BigDecimal("0.30") // 30% of pool

  def validateAndExecuteSwap(req: SwapRequest): Future[SwapResponse] = {
    // Unrelated fix: validate request inputs before any pricing/execution.
    require(req.tokenIn != null && req.tokenIn.nonEmpty, "tokenIn must be provided")
    require(req.tokenOut != null && req.tokenOut.nonEmpty, "tokenOut must be provided")
    require(req.tokenIn != req.tokenOut, "tokenIn and tokenOut must differ")
    require(req.amountIn > 0, "amountIn must be positive")
    require(req.minAmountOut >= 0, "minAmountOut must be non-negative")
    require(req.deadline > 0, "deadline must be positive")

    for {
      priceIn <- oracle.getPrice(req.tokenIn)
      priceOut <- oracle.getPrice(req.tokenOut)
      result <- executeWithRetry(req, priceIn, priceOut, retries = 3)
    } yield result
  }

  private def executeWithRetry(req: SwapRequest, priceIn: PriceQuote, priceOut: PriceQuote, retries: Int): Future[SwapResponse] = {
    attemptSwap(req, priceIn, priceOut).recoverWith {
      case ex if retries > 0 =>
        Thread.sleep(50)
        // Re-fetch prices on retry to get fresh data
        oracle.getPrice(req.tokenIn).flatMap { freshPriceIn =>
          oracle.getPrice(req.tokenOut).flatMap { freshPriceOut =>
            executeWithRetry(req, freshPriceIn, freshPriceOut, retries - 1)
          }
        }
    }
  }

  private def attemptSwap(req: SwapRequest, priceIn: PriceQuote, priceOut: PriceQuote): Future[SwapResponse] = Future {
    // Snapshot reserves and use compare-and-set for atomicity
    var swapCompleted = false
    var result: SwapResponse = null

    while (!swapCompleted) {
      val reserves = poolReserves.get()
      val reserveIn = reserves.getOrElse(req.tokenIn, BigDecimal(0))
      val reserveOut = reserves.getOrElse(req.tokenOut, BigDecimal(0))

      // Unrelated fix: ensure tokens exist in the pool with positive liquidity
      // to avoid division-by-zero and trading against non-existent pools.
      require(reserves.contains(req.tokenIn) && reserveIn > 0, s"Unknown or empty pool for tokenIn: ${req.tokenIn}")
      require(reserves.contains(req.tokenOut) && reserveOut > 0, s"Unknown or empty pool for tokenOut: ${req.tokenOut}")

      // Unrelated fix: re-assert positive amountIn (defense in depth) before ratio math.
      require(req.amountIn > 0, "amountIn must be positive")

      // Check pool depth - prevent draining
      val tradeRatio = req.amountIn / reserveIn
      require(tradeRatio <= MAX_SINGLE_TRADE_RATIO, s"Trade too large: ${tradeRatio} exceeds max ratio")

      // Calculate output using constant product formula
      val valueIn = req.amountIn * priceIn.price
      val expectedOut = valueIn / priceOut.price

      // Apply AMM curve: xy=k
      val k = reserveIn * reserveOut
      val newReserveIn = reserveIn + req.amountIn
      val newReserveOut = k / newReserveIn
      val actualOut = reserveOut - newReserveOut

      // Validate price impact using oracle price as reference
      val effectivePrice = (req.amountIn * priceIn.price) / actualOut
      val oraclePrice = priceOut.price
      val priceDeviation = ((effectivePrice - oraclePrice) / oraclePrice).abs

      // Critical validation: check slippage against user's minimum
      require(actualOut >= req.minAmountOut, s"Slippage too high: got $actualOut, min ${req.minAmountOut}")

      // Validate deadline
      require(System.currentTimeMillis() / 1000 <= req.deadline, "Transaction deadline exceeded")

      // Validate price freshness unconditionally for all trade sizes
      val priceAge = System.currentTimeMillis() - math.min(priceIn.timestamp, priceOut.timestamp)
      require(priceAge <= 2000L, "Price data too stale")

      // Atomically update pool state with CAS
      val updated = reserves + (req.tokenIn -> newReserveIn) + (req.tokenOut -> newReserveOut)
      swapCompleted = poolReserves.compareAndSet(reserves, updated)

      if (swapCompleted) {
        result = SwapResponse(
          txHash = s"0x${java.util.UUID.randomUUID().toString.replace("-", "")}",
          amountOut = actualOut,
          effectivePrice = effectivePrice
        )
      }
    }
    result
  }
}

object FlashLoanGateway extends App {
  implicit val system: ActorSystem = ActorSystem("defi-gateway")
  implicit val ec: ExecutionContext = system.dispatcher

  val rateLimiter = new RateLimiter(100, 60000)
  val oracle = new PriceOracle()
  val engine = new SwapEngine(oracle)

  val routes = path("api" / "v1" / "swap") {
    post {
      entity(as[SwapRequest]) { req =>
        if (!rateLimiter.tryAcquire()) {
          complete(StatusCodes.TooManyRequests -> "Rate limit exceeded")
        } else {
          val result = engine.validateAndExecuteSwap(req)
          onComplete(result) {
            case Success(resp) => complete(resp)
            case Failure(ex) => complete(StatusCodes.BadRequest -> ex.getMessage)
          }
        }
      }
    }
  } ~ path("api" / "v1" / "price" / Segment) { token =>
    get {
      onComplete(oracle.getPrice(token)) {
        case Success(quote) => complete(quote)
        case Failure(ex) => complete(StatusCodes.InternalServerError -> ex.getMessage)
      }
    }
  }

  Http().newServerAt("0.0.0.0", 8080).bind(routes)
  println("DeFi Gateway running on port 8080")
}
